using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 科技树管理器 (持久化单例) — 管理科技点、节点解锁、属性加成计算。
///
/// 生命周期:
///   - 通过 [RuntimeInitializeOnLoadMethod] 自动创建，DontDestroyOnLoad
///   - 科技点和解锁状态通过 TechTreeSaveSystem 持久化（跨游戏会话保留）
///
/// 核心接口:
///   - TechPoints: 当前可用科技点
///   - GetStatBonus(statName): 获取某属性的累计加成
///   - GetAllBonuses(): 获取所有属性的加成字典（供 PlayerManager 使用）
///   - CanUnlock(nodeId) / Unlock(nodeId): 解锁逻辑
///   - AddTechPoints(amount): 结算时发放科技点
/// </summary>
public class TechTreeManager : MonoBehaviour
{
    public static TechTreeManager Instance { get; private set; }

    // ========== 配置 ==========

    private const string CONFIG_PATH = "TechTree/TechTreeConfig";

    [Header("科技树配置")]
    [SerializeField] private TechTreeConfig _config;

    // ========== 运行时状态 ==========

    /// <summary>当前可用科技点</summary>
    public int TechPoints { get; private set; }

    /// <summary>已解锁节点ID集合</summary>
    private readonly HashSet<string> _unlockedNodeIds = new();

    /// <summary>已解锁节点ID（只读视图）</summary>
    public IReadOnlyCollection<string> UnlockedNodeIds => _unlockedNodeIds;

    /// <summary>属性加成缓存: statName → 累计加成值</summary>
    private readonly Dictionary<string, float> _statBonuses = new();

    /// <summary>科技点变化事件</summary>
    public event System.Action<int> OnTechPointsChanged;

    /// <summary>节点解锁事件: 参数为节点ID</summary>
    public event System.Action<string> OnNodeUnlocked;

    // ========== 生命周期 ==========

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void AutoInitialize()
    {
        if (Instance != null) return;
        var go = new GameObject("[TechTreeManager]");
        go.AddComponent<TechTreeManager>();
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);

        // 自动加载配置
        if (_config == null)
        {
            _config = Resources.Load<TechTreeConfig>(CONFIG_PATH);
        }

        // 加载持久化数据
        Load();
        RecalculateBonuses();
    }

    private void OnEnable()
    {
        if (Instance == null)
        {
            Instance = this;
        }
    }

    // ========== 公开接口 ==========

    /// <summary>科技树配置</summary>
    public TechTreeConfig Config => _config;

    /// <summary>获取某属性的累计科技树加成</summary>
    public float GetStatBonus(string statName)
    {
        return _statBonuses.TryGetValue(statName, out float bonus) ? bonus : 0f;
    }

    /// <summary>获取所有属性的加成字典（供 PlayerManager 应用到 PlayerStats）</summary>
    public Dictionary<string, float> GetAllBonuses()
    {
        return new Dictionary<string, float>(_statBonuses);
    }

    /// <summary>增加科技点（结算时调用）</summary>
    public void AddTechPoints(int amount)
    {
        if (amount <= 0) return;
        TechPoints += amount;
        Save();
        OnTechPointsChanged?.Invoke(TechPoints);
    }

    /// <summary>判断节点是否已解锁</summary>
    public bool IsUnlocked(string nodeId) => _unlockedNodeIds.Contains(nodeId);

    /// <summary>判断节点是否可以解锁（点数足够 + 前置满足）</summary>
    public bool CanUnlock(string nodeId)
    {
        if (_config == null) return false;
        var node = _config.GetNodeById(nodeId);
        if (node == null) return false;
        if (_unlockedNodeIds.Contains(nodeId)) return false;
        if (TechPoints < node.Cost) return false;

        // 检查前置条件
        if (node.PreviousNodes != null)
        {
            foreach (var prereq in node.PreviousNodes)
            {
                if (prereq == null) continue;
                if (!_unlockedNodeIds.Contains(prereq.NodeId))
                    return false;
            }
        }
        return true;
    }

    /// <summary>解锁节点（扣除科技点、记录、重算加成）</summary>
    public bool Unlock(string nodeId)
    {
        if (!CanUnlock(nodeId)) return false;

        var node = _config.GetNodeById(nodeId);
        TechPoints -= node.Cost;
        _unlockedNodeIds.Add(nodeId);
        RecalculateBonuses();
        Save();

        OnTechPointsChanged?.Invoke(TechPoints);
        OnNodeUnlocked?.Invoke(nodeId);

        return true;
    }

    /// <summary>重置所有科技树进度（调试用）</summary>
    public void ResetAll()
    {
        TechPoints = 0;
        _unlockedNodeIds.Clear();
        _statBonuses.Clear();
        TechTreeSaveSystem.Clear();
        OnTechPointsChanged?.Invoke(TechPoints);
    }

    // ========== 内部方法 ==========

    /// <summary>重新计算所有已解锁节点的属性加成</summary>
    private void RecalculateBonuses()
    {
        _statBonuses.Clear();
        if (_config == null) return;

        foreach (var nodeId in _unlockedNodeIds)
        {
            var node = _config.GetNodeById(nodeId);
            if (node == null) continue;
            if (node.Effect == null) continue;

            node.Effect.ApplyBonus(_statBonuses);
        }
    }

    // ========== 持久化（委托 TechTreeSaveSystem）==========

    private void Save()
    {
        var data = new TechTreeSaveData
        {
            techPoints = TechPoints,
            unlockedNodeIds = new List<string>(_unlockedNodeIds)
        };
        TechTreeSaveSystem.Save(data);
    }

    private void Load()
    {
        _unlockedNodeIds.Clear();
        TechPoints = 0;

        var data = TechTreeSaveSystem.Load();
        TechPoints = data.techPoints;
        if (data.unlockedNodeIds != null)
        {
            foreach (var id in data.unlockedNodeIds)
                _unlockedNodeIds.Add(id);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 科技树 UI 控制器 (MVC Controller) — 类似 SkillUIController。
/// 从 TechTreeConfig 的根节点 BFS 遍历，实例化 TechTreeNodeView 预制体。
/// 构建 TechTreeNodeViewData 推给 View，处理节点解锁和连线刷新。
///
/// 使用方式:
///   TechTreeUIController.Show()  — 打开面板
///   TechTreeUIController.Hide()  — 关闭面板
/// </summary>
public class TechTreeUIController : MonoBehaviour
{
    // ========== 布局常量 ==========

    private const float NODE_WIDTH = 160f;
    private const float NODE_HEIGHT = 100f;
    private const float NODE_SPACING_X = 60f;
    private const float NODE_SPACING_Y = 40f;
    private const float TREE_ORIGIN_X = -600f;
    private const float TREE_ORIGIN_Y = 200f;
    private const int BEZIER_SEGMENTS = 12;

    // ========== 颜色 ==========

    private static readonly Color PanelBgColor = new(0.1f, 0.1f, 0.15f, 0.95f);
    private static readonly Color HeaderColor = new(0.15f, 0.15f, 0.2f, 1f);
    private static readonly Color LineColor = new(0.4f, 0.4f, 0.5f, 0.6f);
    private static readonly Color ActiveLineColor = new(0.2f, 0.8f, 0.2f, 0.6f);
    private static readonly Color TitleColor = new(1f, 0.85f, 0.2f);
    private static readonly Color InfoColor = new(0.85f, 0.85f, 0.9f);

    // ========== UI 引用 ==========

    private GameObject _backdrop;
    private GameObject _panel;
    private TMP_Text _techPointsText;
    private TMP_Text _hintText;
    private readonly Dictionary<string, TechTreeNodeView> _nodeViews = new();
    private readonly Dictionary<string, Vector2> _nodePositions = new();
    private GameObject _lineLayer;
    private TechTreeNodeView _nodeViewPrefab;

    // ========== 单例（场景级） ==========

    private static TechTreeUIController _instance;
    private static TechTreeUIController Instance
    {
        get
        {
            if (_instance != null) return _instance;
            _instance = FindObjectOfType<TechTreeUIController>(true);
            if (_instance == null)
            {
                _instance = CreatePanel();
            }
            return _instance;
        }
    }

    // ========== 公开接口 ==========

    public static void Show()
    {
        var inst = Instance;
        inst.gameObject.SetActive(true);
        inst.Refresh();
    }

    public static void Hide()
    {
        if (_instance != null)
            _instance.gameObject.SetActive(false);
    }

    public static void Toggle()
    {
        var inst = Instance;
        if (inst.gameObject.activeSelf)
            Hide();
        else
            Show();
    }

    // ========== 初始化 ==========

    private void Awake()
    {
        _instance = this;
        LoadPrefab();
        BuildUI();
        gameObject.SetActive(false);

        if (TechTreeManager.Instance != null)
        {
            TechTreeManager.Instance.OnTechPointsChanged += _ => Refresh();
            TechTreeManager.Instance.OnNodeUnlocked += _ => Refresh();
        }
    }

    private void OnDestroy()
    {
        if (TechTreeManager.Instance != null)
        {
            TechTreeManager.Instance.OnTechPointsChanged -= _ => Refresh();
            TechTreeManager.Instance.OnNodeUnlocked -= _ => Refresh();
        }
    }

    /// <summary>加载节点预制体</summary>
    private void LoadPrefab()
    {
        _nodeViewPrefab = Resources.Load<TechTreeNodeView>("TechTree/TechTreeNodeView");
    }

    // ========== UI 构建 ==========

    private static TechTreeUIController CreatePanel()
    {
        Canvas rootCanvas = FindObjectOfType<Canvas>();
        if (rootCanvas == null)
        {
            var canvasGo = new GameObject("TechTreeCanvas");
            rootCanvas = canvasGo.AddComponent<Canvas>();
            rootCanvas.renderMode = RenderMode.ScreenSpaceOverlay;
            var scaler = canvasGo.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920, 1080);
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.Expand;
            scaler.matchWidthOrHeight = 0.5f;
            canvasGo.AddComponent<GraphicRaycaster>();
        }

        var go = new GameObject("TechTreePanel");
        go.layer = 5;
        go.AddComponent<RectTransform>();
        go.transform.SetParent(rootCanvas.transform, false);
        var ctrl = go.AddComponent<TechTreeUIController>();
        return ctrl;
    }

    private void BuildUI()
    {
        var rootRt = GetComponent<RectTransform>();
        rootRt.anchorMin = Vector2.zero;
        rootRt.anchorMax = Vector2.one;
        rootRt.offsetMin = Vector2.zero;
        rootRt.offsetMax = Vector2.zero;

        // === 背景遮罩 ===
        _backdrop = CreateChild("Backdrop", transform);
        StretchToParent(_backdrop);
        var backdropImg = _backdrop.AddComponent<Image>();
        backdropImg.color = new Color(0, 0, 0, 0.6f);
        var backdropBtn = _backdrop.AddComponent<Button>();
        backdropBtn.transition = Selectable.Transition.None;
        backdropBtn.onClick.AddListener(Hide);

        // === 主面板 ===
        _panel = CreateChild("Panel", transform);
        var panelRt = _panel.GetComponent<RectTransform>();
        panelRt.anchorMin = new Vector2(0.05f, 0.05f);
        panelRt.anchorMax = new Vector2(0.95f, 0.95f);
        panelRt.offsetMin = Vector2.zero;
        panelRt.offsetMax = Vector2.zero;
        var panelImg = _panel.AddComponent<Image>();
        panelImg.color = PanelBgColor;

        // === 标题栏 ===
        var header = CreateChild("Header", _panel.transform);
        var headerRt = header.GetComponent<RectTransform>();
        headerRt.anchorMin = new Vector2(0, 1);
        headerRt.anchorMax = new Vector2(1, 1);
        headerRt.pivot = new Vector2(0.5f, 1);
        headerRt.sizeDelta = new Vector2(0, 60);
        headerRt.anchoredPosition = Vector2.zero;
        var headerImg = header.AddComponent<Image>();
        headerImg.color = HeaderColor;
        headerImg.raycastTarget = false;

        // 标题文本
        var titleGo = CreateChild("TitleText", header.transform);
        var titleRt = titleGo.GetComponent<RectTransform>();
        titleRt.anchorMin = new Vector2(0, 0);
        titleRt.anchorMax = new Vector2(0.7f, 1);
        titleRt.offsetMin = new Vector2(20, 0);
        titleRt.offsetMax = Vector2.zero;
        var titleText = titleGo.AddComponent<TextMeshProUGUI>();
        titleText.text = "科 技 树";
        titleText.fontSize = 28;
        titleText.fontStyle = FontStyles.Bold;
        titleText.color = TitleColor;
        titleText.alignment = TextAlignmentOptions.Left;
        titleText.verticalAlignment = VerticalAlignmentOptions.Middle;
        titleText.raycastTarget = false;

        // 科技点显示
        var pointsGo = CreateChild("TechPointsText", header.transform);
        var pointsRt = pointsGo.GetComponent<RectTransform>();
        pointsRt.anchorMin = new Vector2(0.7f, 0);
        pointsRt.anchorMax = new Vector2(1, 1);
        pointsRt.offsetMin = Vector2.zero;
        pointsRt.offsetMax = new Vector2(-70, 0);
        _techPointsText = pointsGo.AddComponent<TextMeshProUGUI>();
        _techPointsText.fontSize = 22;
        _techPointsText.fontStyle = FontStyles.Bold;
        _techPointsText.color = new Color(0.4f, 1f, 0.4f);
        _techPointsText.alignment = TextAlignmentOptions.Right;
        _techPointsText.verticalAlignment = VerticalAlignmentOptions.Middle;
        _techPointsText.raycastTarget = false;

        // 关闭按钮
        var closeBtnGo = CreateChild("CloseButton", header.transform);
        var closeRt = closeBtnGo.GetComponent<RectTransform>();
        closeRt.anchorMin = new Vector2(1, 0.5f);
        closeRt.anchorMax = new Vector2(1, 0.5f);
        closeRt.pivot = new Vector2(1, 0.5f);
        closeRt.sizeDelta = new Vector2(50, 50);
        closeRt.anchoredPosition = new Vector2(-10, 0);
        var closeImg = closeBtnGo.AddComponent<Image>();
        closeImg.color = new Color(0.6f, 0.2f, 0.2f, 1f);
        var closeBtn = closeBtnGo.AddComponent<Button>();
        var closeColors = closeBtn.colors;
        closeColors.highlightedColor = new Color(0.8f, 0.3f, 0.3f, 1f);
        closeBtn.colors = closeColors;
        closeBtn.onClick.AddListener(Hide);
        var closeTextGo = CreateChild("Text", closeBtnGo.transform);
        var closeTextRt = closeTextGo.GetComponent<RectTransform>();
        closeTextRt.anchorMin = Vector2.zero;
        closeTextRt.anchorMax = Vector2.one;
        closeTextRt.offsetMin = Vector2.zero;
        closeTextRt.offsetMax = Vector2.zero;
        var closeText = closeTextGo.AddComponent<TextMeshProUGUI>();
        closeText.text = "×";
        closeText.fontSize = 36;
        closeText.color = Color.white;
        closeText.alignment = TextAlignmentOptions.Center;
        closeText.verticalAlignment = VerticalAlignmentOptions.Middle;
        closeText.raycastTarget = false;

        // === 提示文本 ===
        var hintGo = CreateChild("HintText", _panel.transform);
        var hintRt = hintGo.GetComponent<RectTransform>();
        hintRt.anchorMin = new Vector2(0, 0);
        hintRt.anchorMax = new Vector2(1, 0);
        hintRt.pivot = new Vector2(0.5f, 0);
        hintRt.sizeDelta = new Vector2(0, 30);
        hintRt.anchoredPosition = new Vector2(0, 10);
        _hintText = hintGo.AddComponent<TextMeshProUGUI>();
        _hintText.fontSize = 14;
        _hintText.color = InfoColor;
        _hintText.alignment = TextAlignmentOptions.Center;
        _hintText.raycastTarget = false;

        // === ScrollView ===
        var scrollGo = CreateChild("NodeScrollView", _panel.transform);
        var scrollRt = scrollGo.GetComponent<RectTransform>();
        scrollRt.anchorMin = new Vector2(0, 0.05f);
        scrollRt.anchorMax = new Vector2(1, 1);
        scrollRt.offsetMin = new Vector2(0, 30);
        scrollRt.offsetMax = Vector2.zero;
        var scrollRect = scrollGo.AddComponent<ScrollRect>();
        scrollRect.horizontal = true;
        scrollRect.vertical = true;

        var viewportGo = CreateChild("Viewport", scrollGo.transform);
        var viewportRt = viewportGo.GetComponent<RectTransform>();
        viewportRt.anchorMin = Vector2.zero;
        viewportRt.anchorMax = Vector2.one;
        viewportRt.pivot = new Vector2(0, 1);
        viewportRt.offsetMin = Vector2.zero;
        viewportRt.offsetMax = Vector2.zero;
        viewportGo.AddComponent<RectMask2D>();
        scrollRect.viewport = viewportRt;

        var contentGo = CreateChild("Content", viewportGo.transform);
        var contentRt = contentGo.GetComponent<RectTransform>();
        contentRt.anchorMin = new Vector2(0, 1);
        contentRt.anchorMax = new Vector2(0, 1);
        contentRt.pivot = new Vector2(0, 1);
        contentRt.sizeDelta = new Vector2(1400, 800);
        contentRt.anchoredPosition = Vector2.zero;
        scrollRect.content = contentRt;

        // 连线层
        _lineLayer = CreateChild("LineLayer", contentGo.transform);
        StretchToParent(_lineLayer);
        _lineLayer.transform.SetAsFirstSibling();

        // 创建节点
        CreateNodes(contentGo.transform);
        // 创建连线
        CreateLines(_lineLayer.transform);
    }

    /// <summary>从根节点 BFS 遍历，实例化预制体</summary>
    private void CreateNodes(Transform contentParent)
    {
        var config = TechTreeManager.Instance?.Config;
        if (config == null || config.RootNodes == null) return;

        var allNodes = config.GetAllNodes();
        foreach (var node in allNodes)
        {
            var view = InstantiateNodeView(contentParent, node);
            if (view != null)
            {
                _nodeViews[node.NodeId] = view;
                _nodePositions[node.NodeId] = NodeToAnchoredPos(node.Position);
            }
        }
    }

    /// <summary>实例化单个节点视图</summary>
    private TechTreeNodeView InstantiateNodeView(Transform parent, TechTreeNodeData node)
    {
        TechTreeNodeView view;
        if (_nodeViewPrefab != null)
        {
            var go = Object.Instantiate(_nodeViewPrefab.gameObject, parent, false);
            go.name = $"Node_{node.NodeId}";
            go.layer = 5;
            view = go.GetComponent<TechTreeNodeView>();
        }
        else
        {
            // 无预制体时代码构建
            var go = new GameObject($"Node_{node.NodeId}");
            go.transform.SetParent(parent, false);
            go.layer = 5;
            var rt = go.AddComponent<RectTransform>();
            rt.sizeDelta = new Vector2(NODE_WIDTH, NODE_HEIGHT);
            rt.pivot = new Vector2(0.5f, 0.5f);
            view = go.AddComponent<TechTreeNodeView>();
        }

        var rt2 = view.GetComponent<RectTransform>();
        rt2.sizeDelta = new Vector2(NODE_WIDTH, NODE_HEIGHT);
        rt2.pivot = new Vector2(0.5f, 0.5f);
        rt2.anchoredPosition = NodeToAnchoredPos(node.Position);

        return view;
    }

    /// <summary>创建贝塞尔曲线连线</summary>
    private void CreateLines(Transform lineParent)
    {
        var config = TechTreeManager.Instance?.Config;
        if (config == null || config.RootNodes == null) return;

        var allNodes = config.GetAllNodes();
        foreach (var node in allNodes)
        {
            if (node.NextNodes == null) continue;
            foreach (var nextNode in node.NextNodes)
            {
                if (nextNode == null) continue;
                if (!_nodePositions.TryGetValue(node.NodeId, out var start) ||
                    !_nodePositions.TryGetValue(nextNode.NodeId, out var end))
                    continue;

                bool unlocked = TechTreeManager.Instance != null && TechTreeManager.Instance.IsUnlocked(node.NodeId);
                CreateBezierLine(lineParent, start, end, node.NodeId, unlocked);
            }
        }
    }

    /// <summary>创建贝塞尔曲线连线（多段 Image 模拟）</summary>
    private void CreateBezierLine(Transform parent, Vector2 start, Vector2 end, string fromNodeId, bool unlocked)
    {
        // 从节点右边缘到目标左边缘
        var startRight = new Vector2(start.x + NODE_WIDTH / 2f, start.y);
        var endLeft = new Vector2(end.x - NODE_WIDTH / 2f, end.y);

        // 贝塞尔控制点：水平延伸
        float dx = endLeft.x - startRight.x;
        var cp1 = new Vector2(startRight.x + dx * 0.5f, startRight.y);
        var cp2 = new Vector2(endLeft.x - dx * 0.5f, endLeft.y);

        Color lineColor = unlocked ? ActiveLineColor : LineColor;

        Vector2 prev = startRight;
        for (int i = 1; i <= BEZIER_SEGMENTS; i++)
        {
            float t = (float)i / BEZIER_SEGMENTS;
            var curr = BezierPoint(startRight, cp1, cp2, endLeft, t);
            CreateLineSegment(parent, prev, curr, lineColor);
            prev = curr;
        }
    }

    /// <summary>三次贝塞尔曲线点</summary>
    private static Vector2 BezierPoint(Vector2 p0, Vector2 p1, Vector2 p2, Vector2 p3, float t)
    {
        float u = 1f - t;
        return u * u * u * p0 + 3f * u * u * t * p1 + 3f * u * t * t * p2 + t * t * t * p3;
    }

    /// <summary>创建单段直线</summary>
    private void CreateLineSegment(Transform parent, Vector2 from, Vector2 to, Color color)
    {
        var go = new GameObject("Line");
        go.transform.SetParent(parent, false);
        go.layer = 5;

        var rt = go.AddComponent<RectTransform>();
        var img = go.AddComponent<Image>();
        img.color = color;

        Vector2 delta = to - from;
        float length = delta.magnitude;
        float angle = Mathf.Atan2(delta.y, delta.x) * Mathf.Rad2Deg;

        rt.sizeDelta = new Vector2(length, 3f);
        rt.pivot = new Vector2(0, 0.5f);
        rt.anchoredPosition = from;
        rt.localEulerAngles = new Vector3(0, 0, angle);
    }

    // ========== 刷新 ==========

    private void Refresh()
    {
        var mgr = TechTreeManager.Instance;
        if (mgr == null) return;

        // 科技点显示
        if (_techPointsText != null)
            _techPointsText.text = $"科技点: {mgr.TechPoints}";

        // 提示文本
        if (_hintText != null)
        {
            int unlockedCount = 0;
            int totalCount = 0;
            if (mgr.Config != null)
            {
                var all = mgr.Config.GetAllNodes();
                totalCount = all.Count;
                foreach (var node in all)
                {
                    if (mgr.IsUnlocked(node.NodeId)) unlockedCount++;
                }
            }
            _hintText.text = $"已解锁: {unlockedCount}/{totalCount}  |  点击节点解锁，获得属性加成";
        }

        // 刷新节点视图
        foreach (var kvp in _nodeViews)
        {
            var node = mgr.Config?.GetNodeById(kvp.Key);
            if (node == null) continue;

            var data = new TechTreeNodeViewData
            {
                NodeId = node.NodeId,
                DisplayName = node.DisplayName,
                Description = node.Description,
                EffectSummary = node.Effect != null ? node.Effect.GetEffectSummary() : "",
                Cost = node.Cost,
                IsUnlocked = mgr.IsUnlocked(node.NodeId),
                CanUnlock = mgr.CanUnlock(node.NodeId),
                CurrentTechPoints = mgr.TechPoints
            };
            kvp.Value.Configure(data, OnNodeClicked);
            kvp.Value.Refresh(in data);
        }

        // 刷新连线
        RefreshLines();
    }

    private void RefreshLines()
    {
        if (_lineLayer == null) return;

        foreach (Transform child in _lineLayer.transform)
        {
            Destroy(child.gameObject);
        }
        CreateLines(_lineLayer.transform);
    }

    // ========== 事件处理 ==========

    private void OnNodeClicked(string nodeId)
    {
        var mgr = TechTreeManager.Instance;
        if (mgr == null) return;

        if (mgr.CanUnlock(nodeId))
        {
            mgr.Unlock(nodeId);
        }
    }

    // ========== 辅助 ==========

    private static GameObject CreateChild(string name, Transform parent)
    {
        var go = new GameObject(name);
        go.transform.SetParent(parent, false);
        go.layer = 5;
        go.AddComponent<RectTransform>();
        return go;
    }

    private static void StretchToParent(GameObject go)
    {
        var rt = go.GetComponent<RectTransform>();
        rt.anchorMin = Vector2.zero;
        rt.anchorMax = Vector2.one;
        rt.offsetMin = Vector2.zero;
        rt.offsetMax = Vector2.zero;
    }

    private static Vector2 NodeToAnchoredPos(Vector2 nodePos)
    {
        return new Vector2(
            TREE_ORIGIN_X + nodePos.x * (NODE_WIDTH + NODE_SPACING_X),
            TREE_ORIGIN_Y - nodePos.y * (NODE_HEIGHT + NODE_SPACING_Y)
        );
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 科技树节点视图 — 纯渲染组件，类似 SkillSlotView。
/// 不包含任何游戏逻辑，仅接受 TechTreeNodeViewData 进行显示。
/// 预制体上挂载此组件，UI 元素通过 [SerializeField] 引用。
/// </summary>
public class TechTreeNodeView : MonoBehaviour
{
    [Header("UI 引用")]
    [SerializeField] private Image _background;
    [SerializeField] private Image _border;
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _effectText;
    [SerializeField] private TMP_Text _costText;
    [SerializeField] private Button _button;

    // 状态颜色
    private static readonly Color UnlockedColor = new(0.2f, 0.6f, 0.2f, 1f);
    private static readonly Color AvailableColor = new(0.85f, 0.75f, 0.2f, 1f);
    private static readonly Color LockedColor = new(0.45f, 0.45f, 0.5f, 1f);
    private static readonly Color UnlockedTextColor = new(0.85f, 1f, 0.85f);
    private static readonly Color AvailableTextColor = Color.white;
    private static readonly Color LockedTextColor = new(0.75f, 0.75f, 0.8f);

    // 边框颜色
    private static readonly Color UnlockedBorderColor = new(0.3f, 0.9f, 0.3f, 1f);
    private static readonly Color AvailableBorderColor = new(1f, 0.9f, 0.3f, 1f);
    private static readonly Color LockedBorderColor = new(0.5f, 0.5f, 0.55f, 0.5f);

    // 效果文字颜色（正数=绿色，负数=红色）
    private static readonly Color PositiveEffectColor = new(0.4f, 1f, 0.4f);
    private static readonly Color NegativeEffectColor = new(1f, 0.4f, 0.4f);

    private TechTreeNodeViewData _data;
    private System.Action<string> _onClick;

    /// <summary>配置节点数据和点击回调</summary>
    public void Configure(TechTreeNodeViewData data, System.Action<string> onClick)
    {
        _data = data;
        _onClick = onClick;

        if (_button != null)
        {
            _button.onClick.RemoveAllListeners();
            _button.onClick.AddListener(OnClick);
        }
    }

    /// <summary>刷新显示（纯渲染，不包含逻辑）</summary>
    public void Refresh(in TechTreeNodeViewData data)
    {
        _data = data;

        if (_nameText != null)
            _nameText.text = data.DisplayName;
        if (_effectText != null)
        {
            _effectText.text = data.EffectSummary;
            _effectText.color = string.IsNullOrEmpty(data.EffectSummary) ? Color.white
                : (data.EffectSummary.StartsWith("+") ? PositiveEffectColor : NegativeEffectColor);
        }

        Color bgColor, textColor, borderColor;
        if (data.IsUnlocked)
        {
            bgColor = UnlockedColor;
            textColor = UnlockedTextColor;
            borderColor = UnlockedBorderColor;
            if (_costText != null)
                _costText.text = "已解锁";
            if (_button != null)
                _button.interactable = false;
        }
        else if (data.CanUnlock)
        {
            bgColor = AvailableColor;
            textColor = AvailableTextColor;
            borderColor = AvailableBorderColor;
            if (_costText != null)
                _costText.text = $"消耗 {data.Cost} 点";
            if (_button != null)
                _button.interactable = true;
        }
        else
        {
            bgColor = LockedColor;
            textColor = LockedTextColor;
            borderColor = LockedBorderColor;
            if (_costText != null)
            {
                _costText.text = data.CurrentTechPoints < data.Cost
                    ? $"需 {data.Cost} 点"
                    : "前置未满足";
            }
            if (_button != null)
                _button.interactable = false;
        }

        if (_background != null)
            _background.color = bgColor;
        if (_border != null)
            _border.color = borderColor;
        if (_nameText != null)
            _nameText.color = textColor;
        if (_costText != null)
            _costText.color = textColor;
    }

    /// <summary>获取当前节点ID</summary>
    public string NodeId => _data.NodeId;

    private void OnClick()
    {
        _onClick?.Invoke(_data.NodeId);
    }
}

using UnityEngine;

/// <summary>
/// 科技树节点视图数据 (DTO) — 从 Model 构建传递给 View 的不可变数据。
/// 类似 SkillViewData，实现 IEquatable 用于变化检测。
/// </summary>
public struct TechTreeNodeViewData : System.IEquatable<TechTreeNodeViewData>
{
    public string NodeId;
    public string DisplayName;
    public string Description;
    public string EffectSummary;
    public int Cost;
    public bool IsUnlocked;
    public bool CanUnlock;
    public int CurrentTechPoints;

    public bool Equals(TechTreeNodeViewData other)
    {
        return NodeId == other.NodeId
            && DisplayName == other.DisplayName
            && Description == other.Description
            && EffectSummary == other.EffectSummary
            && Cost == other.Cost
            && IsUnlocked == other.IsUnlocked
            && CanUnlock == other.CanUnlock
            && CurrentTechPoints == other.CurrentTechPoints;
    }

    public override bool Equals(object obj) => obj is TechTreeNodeViewData other && Equals(other);
    public override int GetHashCode() => NodeId?.GetHashCode() ?? 0;
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 科技树配置 (ScriptableObject) — 只保存根节点（无前置的节点）。
/// 加载时从根节点开始通过 nextNodes 递归遍历整棵树。
/// 修改/扩展科技树只需增删 TechTreeNodeData 资产并在根节点列表中配置引用。
/// 右键 -> Create -> TechTree -> Tech Tree Config 创建。
/// </summary>
[CreateAssetMenu(menuName = "TechTree/Tech Tree Config", fileName = "TechTreeConfig")]
public class TechTreeConfig : ScriptableObject
{
    [Header("根节点列表")]
    [Tooltip("没有前置节点的根节点，科技树从此处开始遍历")]
    [SerializeField] private TechTreeNodeData[] _rootNodes;

    /// <summary>根节点列表</summary>
    public TechTreeNodeData[] RootNodes => _rootNodes;

    /// <summary>从根节点 BFS 遍历获取所有节点</summary>
    public List<TechTreeNodeData> GetAllNodes()
    {
        var result = new List<TechTreeNodeData>();
        var visited = new HashSet<TechTreeNodeData>();
        var queue = new Queue<TechTreeNodeData>();

        if (_rootNodes == null) return result;

        foreach (var root in _rootNodes)
        {
            if (root != null && visited.Add(root))
                queue.Enqueue(root);
        }

        while (queue.Count > 0)
        {
            var node = queue.Dequeue();
            result.Add(node);

            if (node.NextNodes != null)
            {
                foreach (var next in node.NextNodes)
                {
                    if (next != null && visited.Add(next))
                        queue.Enqueue(next);
                }
            }
        }

        return result;
    }

    /// <summary>按 ID 查找节点（BFS 遍历）</summary>
    public TechTreeNodeData GetNodeById(string id)
    {
        if (string.IsNullOrEmpty(id)) return null;

        foreach (var node in GetAllNodes())
        {
            if (node.NodeId == id) return node;
        }
        return null;
    }

    /// <summary>判断节点 ID 是否存在</summary>
    public bool ContainsNode(string id) => GetNodeById(id) != null;
}

using UnityEngine;

/// <summary>
/// 科技树节点配置 (ScriptableObject) — 每个节点一个 .asset 文件，类似 SkillData。
/// 节点间通过 previousNodes / nextNodes 直接引用其他 TechTreeNodeData 资产。
/// effect 字段引用 TechTreeEffectBase 资产，实现策略模式。
/// 右键 -> Create -> TechTree -> Node Data 创建。
/// </summary>
[CreateAssetMenu(menuName = "TechTree/Node Data", fileName = "TechTreeNode")]
public class TechTreeNodeData : ScriptableObject
{
    [Header("标识")]
    [Tooltip("唯一标识符（用于 PlayerPrefs 持久化）")]
    [SerializeField] private string _nodeId;

    [Tooltip("显示名称")]
    [SerializeField] private string _displayName;

    [TextArea(2, 4)]
    [Tooltip("节点描述")]
    [SerializeField] private string _description;

    [Header("消耗")]
    [Tooltip("解锁所需科技点")]
    [SerializeField] private int _cost = 1;

    [Header("UI布局")]
    [Tooltip("在科技树面板中的位置 (x=列, y=行)")]
    [SerializeField] private Vector2 _position = Vector2.zero;

    [Header("链表结构")]
    [Tooltip("前置节点（全部解锁后才可解锁本节点）")]
    [SerializeField] private TechTreeNodeData[] _previousNodes;

    [Tooltip("后继节点（本节点解锁后才可解锁后继节点）")]
    [SerializeField] private TechTreeNodeData[] _nextNodes;

    [Header("效果")]
    [Tooltip("解锁后应用的效果策略")]
    [SerializeField] private TechTreeEffectBase _effect;

    // ========== 只读属性 ==========

    public string NodeId => _nodeId;
    public string DisplayName => _displayName;
    public string Description => _description;
    public int Cost => _cost;
    public Vector2 Position => _position;
    public TechTreeNodeData[] PreviousNodes => _previousNodes;
    public TechTreeNodeData[] NextNodes => _nextNodes;
    public TechTreeEffectBase Effect => _effect;
}

