using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 科技树效果策略基类 (ScriptableObject) — 类似 SkillEffectBase。
/// 每种效果类型继承此类，实现 ApplyBonus 和 GetEffectSummary。
/// 效果资产在 Inspector 中拖入 TechTreeNodeData.effect 字段。
/// </summary>
public abstract class TechTreeEffectBase : ScriptableObject
{
    /// <summary>将加成写入字典（供 PlayerStats.ApplyBonuses 使用）</summary>
    public abstract void ApplyBonus(Dictionary<string, float> bonuses);

    /// <summary>返回效果摘要文本（用于 UI 显示）</summary>
    public abstract string GetEffectSummary();
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 属性加成效果 (ScriptableObject) — 科技树效果的具体实现。
/// 配置 statName + bonus，ApplyBonus 时将加成累加到字典中。
/// 右键 -> Create -> TechTree -> Stat Bonus Effect 创建。
/// </summary>
[CreateAssetMenu(menuName = "TechTree/Stat Bonus Effect", fileName = "StatBonusEffect")]
public class StatBonusEffect : TechTreeEffectBase
{
    [Header("属性加成")]
    [Tooltip("加成的属性名: MaxHealth / MoveSpeed / AttackStrength / BulletSpeed / ShotsPerMinute / ColliderRadius")]
    [SerializeField] private string _statName = "MaxHealth";

    [Tooltip("加成值（正数=增加，负数=减少）")]
    [SerializeField] private float _bonus = 0f;

    public string StatName => _statName;
    public float Bonus => _bonus;

    public override void ApplyBonus(Dictionary<string, float> bonuses)
    {
        if (bonuses.ContainsKey(_statName))
            bonuses[_statName] += _bonus;
        else
            bonuses[_statName] = _bonus;
    }

    public override string GetEffectSummary()
    {
        string statDisplay = _statName switch
        {
            "MaxHealth"      => "最大生命",
            "MoveSpeed"      => "移动速度",
            "AttackStrength" => "攻击力",
            "BulletSpeed"    => "子弹速度",
            "ShotsPerMinute" => "射速",
            "ColliderRadius" => "碰撞半径",
            _                => _statName
        };
        string sign = _bonus >= 0 ? "+" : "";
        return $"{sign}{_bonus} {statDisplay}";
    }
}

using UnityEngine;

/// <summary>
/// 科技树存档系统 — 封装 PlayerPrefs 的读写逻辑。
/// 负责 TechTreeSaveData 的 JSON 序列化、持久化和清除。
/// </summary>
public static class TechTreeSaveSystem
{
    private const string SAVE_KEY = "TechTree_SaveData";

    /// <summary>保存到 PlayerPrefs</summary>
    public static void Save(TechTreeSaveData data)
    {
        if (data == null) return;
        string json = JsonUtility.ToJson(data);
        PlayerPrefs.SetString(SAVE_KEY, json);
        PlayerPrefs.Save();
    }

    /// <summary>从 PlayerPrefs 加载，无数据时返回空实例</summary>
    public static TechTreeSaveData Load()
    {
        if (!PlayerPrefs.HasKey(SAVE_KEY))
            return new TechTreeSaveData();

        string json = PlayerPrefs.GetString(SAVE_KEY);
        if (string.IsNullOrEmpty(json))
            return new TechTreeSaveData();

        var data = JsonUtility.FromJson<TechTreeSaveData>(json);
        return data ?? new TechTreeSaveData();
    }

    /// <summary>清除存档</summary>
    public static void Clear()
    {
        PlayerPrefs.DeleteKey(SAVE_KEY);
        PlayerPrefs.Save();
    }
}

